contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint t, uint amount, uint am) public payable {
        require(amount > 0);
        require(am > amount);
        require(amount < type(uint256).max / 2);
        require(address(this).balance >= amount);

        // Deposit: unlockTime is set to max(t, block.timestamp), so it can never be
        // strictly in the past within this same transaction.
        c.Put{value: amount}(t);

        uint balBefore = address(c).balance;
        (, uint accBefore) = c.Acc(address(this));

        // Attempt to withdraw; must fail silently (gate block.timestamp > unlockTime is false).
