        (, uint accAfter) = c.Acc(address(this));
        assert(address(c).balance == balBefore && accAfter >= accBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint t, uint amount, uint am) public payable {
        require(amount > 0);
        // keep the recorded balance strictly below MinSum (1 ether) so the
        // withdrawal gate in Collect can never open
        require(amount < 1 ether);
        require(address(this).balance >= amount);

        // deposit: recorded balance becomes amount (< MinSum)
        c.Put{value: amount}(t);

        uint balBefore = address(c).balance;
        uint testBalBefore = address(this).balance;

        // Collect must silently do nothing (gate: acc.balance >= MinSum fails)
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }

        assert(!reverted
            && address(c).balance == balBefore
            && address(this).balance == testBalBefore);
    }

    receive() external payable {}
}

